import{_ as a,o as t,c as n,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Downloads and updates","description":"","frontmatter":{"title":"Downloads and updates","docId":"user.start.updates","translationKey":"user.start.updates","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","translationRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","order":40},"headers":[],"relativePath":"en/user/updates.md","filePath":"en/user/updates.md","lastUpdated":1794611623000}'),o={name:"en/user/updates.md"};function s(l,e,r,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="downloads-and-updates" tabindex="-1">Downloads and updates <a class="header-anchor" href="#downloads-and-updates" aria-label="Permalink to &quot;Downloads and updates {#downloads-and-updates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Choose the right release channel and update without confusing an update check with an automatic installation. Close active sessions and back up local data before changing versions, especially across a documented database migration.</p><h2 id="select-a-channel" tabindex="-1">Select a channel <a class="header-anchor" href="#select-a-channel" aria-label="Permalink to &quot;Select a channel {#select-a-channel}&quot;">​</a></h2><p>The <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">release list</a> identifies stable versions and prereleases. A candidate such as <code>-rc</code> is intended for verification. The application updater distinguishes stable and beta feeds; it authenticates signed metadata before offering a version. An unsigned JSON file or a changed installer is not an accepted update.</p><h2 id="check-and-install" tabindex="-1">Check and install <a class="header-anchor" href="#check-and-install" aria-label="Permalink to &quot;Check and install {#check-and-install}&quot;">​</a></h2><ol><li>Open <strong>Settings → General</strong> and inspect the updater&#39;s current state and installed version.</li><li>Run the available check. Builds without the configured public key/feed capability show that checks are unavailable.</li><li>Read the release notes and choose the package for your platform.</li><li>When the build offers a download/manual handoff, follow that path. The release workflow enables authenticated checks only when the repository public-key variable is configured; automatic installation has additional gates.</li><li>For a manual update, close TikTools, replace or install the complete verified package, and reopen it. Keep the data directory separate from the application files.</li></ol><h2 id="expected-result" tabindex="-1">Expected result <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Expected result {#expected-result}&quot;">​</a></h2><p>The restarted app reports the chosen version and can read the expected local profile. Portable ZIP/TAR packages require manual replacement. Unknown or extracted layouts may also require a manual path even when an AppImage installer exists.</p><h2 id="recovery-and-limitations" tabindex="-1">Recovery and limitations <a class="header-anchor" href="#recovery-and-limitations" aria-label="Permalink to &quot;Recovery and limitations {#recovery-and-limitations}&quot;">​</a></h2><p>A failed signature check is a failed update; download a fresh official copy and verify the release checksums. Do not bypass verification. Automatic AppImage replacement and NSIS handoff have separate build gates and are experimental. There is no general automatic rollback. Returning to an older binary does not undo a migrated SQLite schema.</p><p>Report the installed version, package format and updater error from Diagnostics. Do not attach signing keys, invitation tokens or account data. The <a href="./installation.html">installation guide</a> describes the supported package layouts.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Updater capability is fixed when the app is built. Checks require a configured feed and public key. Automatic AppImage replacement additionally requires the common install gate and a detected supported installation; NSIS requires that same common gate AND the NSIS-specific gate. Setting environment variables after installation does not enable those compiled gates. Portable/extracted/unknown layouts use manual replacement. Verify version, restart and profile after an actual installation; download, checksum or installer launch alone cannot establish completion.</p>',14)])])}const f=a(o,[["render",s]]);export{u as __pageData,f as default};
